using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieves the value of a configuration key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app_name"] = "McpWebService",
            ["version"] = "1.0.0",
            ["environment"] = "production",
            ["max_connections"] = "100"
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Unknown key: {key}";
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerResourceType]
public static class AppResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpWebService",
            Version = "1.0.0",
            Environment = "production",
            MaxConnections = 100,
            Features = new { CachingEnabled = true, RateLimiting = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://endpoints",
        Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Lists available API endpoints and their descriptions.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Method = "POST", Description = "MCP Streamable HTTP endpoint" },
            new { Path = "/health", Method = "GET", Description = "Health check" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

